    private val de7Words = Podcast(
        "de7-words",
        listOf(
            maya("Welcome back. Today is travel words: trains, tickets, the airport, and the times you hear in announcements. These are the words of the listening part, where the station and the airport talk to you. Let's start on the platform."),
